const command = $context.$nodes.XDX_PARSE_CONTROL.$output.result;
const original = $context.$variables && $context.$variables.supplierState;
if (!original || typeof original !== 'object' || !Array.isArray(original.attempts)) return {operation:'display',state:original || null,reason:'Conversation state is not ready; no request can be submitted.'};
const state = JSON.parse(JSON.stringify(original));
const result = {operation:'display',state:state,reason:''};
if(command&&command.kind==='continuation'){
 const matches=state.attempts.filter(function(a){return a.kind==='site'&&a.SupplierSiteId&&a.siteVerification==='verified'&&a.status!=='complete'&&(!command.requestId?!a.continuationOf:a.requestId===command.requestId);});
 if(matches.length!==1){result.reason='Specify the request ID for the incomplete site assignments. No new write was submitted.';return result;}
 const candidate=matches[0],originId=candidate.continuationOf||candidate.requestId,origin=state.attempts.filter(function(a){return a.requestId===originId&&a.kind==='site'&&!a.continuationOf;})[0];
 if(!origin){result.reason='The original site request could not be identified. No new write was submitted.';return result;}
 if(state.draft&&state.draft.requestId!==originId&&state.draft.kind!=='site_continuation'&&!state.attempts.some(function(a){return a.requestId===state.draft.requestId&&a.continuationOf===originId;})){result.reason='Finish or cancel the other draft before preparing this continuation.';return result;}
 if(state.draft&&state.draft.kind==='site_continuation'&&state.draft.originRequestId!==originId){result.reason='Finish or cancel the other continuation draft first.';return result;}
 state.continuationRequest={mode:'prepare',originRequestId:originId};result.operation='site_reconcile';result.reason='Checking the existing site and all existing assignment pairs before preparing a separate continuation.';return result;
}
if (!command || command.kind !== 'control') { result.operation = command && command.kind === 'language' ? 'language' : 'display'; return result; }
const draft = state.draft;
const attempt = state.attempts.filter(function(item){return item.requestId === command.requestId;});
if (attempt.length) {if(['address','contact'].indexOf(attempt[0].kind)>=0)result.kind=attempt[0].kind;result.reason='This request already has a recorded attempt; it will not be submitted again.';result.attempts=attempt;return result;}
if (!draft || draft.requestId !== command.requestId || draft.revision !== command.revision) {result.reason='That request or revision is not current. Review the current draft.';return result;}
result.requestId=draft.requestId;result.revision=draft.revision;
if (draft.status !== 'editing' && draft.status !== 'reviewed') {result.reason='This draft cannot be changed or submitted in its current state.';return result;}
if (command.action === 'cancel'&&draft.kind==='site_continuation'){state.draft=null;delete state.continuationRequest;result.reason='Continuation cancelled. The existing site and assignments remain unchanged; no additional assignment was submitted.';return result;}
if (command.action === 'cancel') {state.draft=null;delete state.childConfirmation;result.reason='Draft cancelled. No '+(draft.kind||'supplier')+' was created.';return result;}
if(draft.kind==='address'||draft.kind==='contact'){
  const address=draft.kind==='address',fields=address?['AddressName','CountryCode','AddressLine1','City','State','PostalCode','Email','AddressPurposeOrderingFlag']:['FirstName','LastName','Email'],p=draft.payload;
  if(!p||Object.keys(p).length!==fields.length||Object.keys(p).some(function(f){return fields.indexOf(f)<0;})||draft.fieldsVerifiedRevision!==draft.revision||address&&draft.duplicateCheckedRevision!==draft.revision||!draft.supplier||String(draft.supplier.SupplierId)!==draft.suppliers_Id||draft.mode==='template'&&(!draft.source||draft.sourceParentId!==draft.suppliers_Id||!draft.sourceId)){result.reason='Complete and validate the required child fields and parent before review.';return result;}
  result.kind=draft.kind;result.mode=draft.mode;result.supplier=draft.supplier;result.payload=JSON.parse(JSON.stringify(p));result.source=draft.source;
  if(command.action==='review'){draft.status='reviewed';draft.reviewedRevision=draft.revision;result.confirmCommand='Confirm request '+draft.requestId+' revision '+draft.revision;result.reason='Review this exact proposed '+draft.kind+' under the displayed supplier. Nothing has been created.';return result;}
  if(command.action!=='confirm'||draft.status!=='reviewed'||draft.reviewedRevision!==draft.revision){result.reason='Review the current child revision before confirming.';return result;}
  state.childConfirmation={kind:draft.kind,requestId:draft.requestId,revision:draft.revision,suppliers_Id:draft.suppliers_Id,payload:JSON.parse(JSON.stringify(p))};result.operation='child_preflight';result.reason='Rechecking the exact reviewed child request before reservation.';return result;
 }
if(draft.kind==='site_continuation'){
 const pairs=draft.assignments,seen={};
 if(!draft.originRequestId||!draft.SupplierSiteId||!draft.suppliers_Id||draft.reconciled!==true||!Array.isArray(pairs)||!pairs.length||pairs.some(function(p){if(!p||Object.keys(p).length!==2||!Number.isSafeInteger(p.ClientBUId)||p.ClientBUId<=0||!Number.isSafeInteger(p.BillToBUId)||p.BillToBUId<=0)return true;const k=p.ClientBUId+':'+p.BillToBUId;if(seen[k])return true;seen[k]=true;return false;})){result.reason='Reconcile the site assignments again before reviewing a continuation.';return result;}
 if(command.action==='review'){draft.status='reviewed';draft.reviewedRevision=draft.revision;result.assignments=JSON.parse(JSON.stringify(pairs));result.site=draft.site;result.SupplierSiteId=draft.SupplierSiteId;result.writeCount=pairs.length;result.writeOrder='Create and independently verify only the missing assignment pairs, serially. The existing site is retained.';result.confirmCommand='Confirm request '+draft.requestId+' revision '+draft.revision;result.reason='Review this separate continuation for the missing assignments. No new write has been submitted.';return result;}
 if(command.action!=='confirm'||draft.status!=='reviewed'||draft.reviewedRevision!==draft.revision){result.reason='Review the current continuation revision before confirming.';return result;}
 state.continuationRequest={mode:'confirm',originRequestId:draft.originRequestId,requestId:draft.requestId,revision:draft.revision,assignments:JSON.parse(JSON.stringify(pairs))};result.operation='site_reconcile';result.reason='Rechecking existing assignments before reserving this missing-only continuation.';return result;
}
if(draft.kind==='site'){
 function siteKey(v){return typeof v==='number'&&Number.isSafeInteger(v)&&v>0;}
 const p=draft.payload,fields=['SupplierSite','ProcurementBUId','SupplierAddressName','SitePurposePurchasingFlag'];
 const pairs=draft.assignments,seen={};
 if(!p||Object.keys(p).length!==4||Object.keys(p).some(function(k){return fields.indexOf(k)<0;})||typeof p.SupplierSite!=='string'||!p.SupplierSite.trim()||p.SupplierSite.length>240||/[\x00-\x1f]/.test(p.SupplierSite)||!siteKey(p.ProcurementBUId)||typeof p.SupplierAddressName!=='string'||!p.SupplierAddressName.trim()||p.SupplierAddressName.length>240||p.SitePurposePurchasingFlag!==true||!draft.supplier||!siteKey(draft.supplier.SupplierId)||!draft.source||!siteKey(draft.source.SupplierSiteId)||draft.source.Status!=='ACTIVE'||draft.source.ProcurementBUId!==p.ProcurementBUId||draft.source.SitePurposePurchasingFlag!==true||!draft.address||draft.address.Status!=='ACTIVE'||draft.address.SupplierAddressId!==draft.source.SupplierAddressId||draft.address.AddressName!==p.SupplierAddressName||draft.source.SupplierAddressName!==p.SupplierAddressName||draft.assignmentsComplete!==true||draft.eligibilityVerified!==true||draft.duplicateCheckedRevision!==draft.revision||!Array.isArray(pairs)||pairs.some(function(pair){if(!pair||Object.keys(pair).length!==2||!siteKey(pair.ClientBUId)||!siteKey(pair.BillToBUId))return true;const key=pair.ClientBUId+':'+pair.BillToBUId;if(seen[key])return true;seen[key]=true;return false;})){
 result.reason='The site draft needs verified source/address/assignment pairs and a current name check before review.';return result;
 }
 if(command.action==='review'){
 draft.status='reviewed';draft.reviewedRevision=draft.revision;result.payload=JSON.parse(JSON.stringify(p));result.source=JSON.parse(JSON.stringify(draft.source));result.supplier=draft.supplier;result.address=draft.address;result.assignments=JSON.parse(JSON.stringify(pairs));result.writeCount=1+pairs.length;result.writeOrder='Create site, independently verify it, then create and verify each assignment serially.';result.confirmCommand='Confirm request '+draft.requestId+' revision '+draft.revision;result.reason='Review the proposed site and exact assignments. Nothing has been created.';return result;
 }
 if(command.action!=='confirm'||draft.status!=='reviewed'||draft.reviewedRevision!==draft.revision){result.reason='Review the current site revision before confirming it.';return result;}
 state.siteConfirmation={requestId:draft.requestId,revision:draft.revision,payload:JSON.parse(JSON.stringify(p)),assignments:JSON.parse(JSON.stringify(pairs)),suppliers_Id:String(draft.supplier.SupplierId),sourceSiteId:String(draft.source.SupplierSiteId),addressId:String(draft.address.SupplierAddressId)};
 result.operation='site_preflight';result.reason='Rechecking the reviewed site source, address, assignments and name before reserving creation.';return result;
}

const fields=['Supplier','SupplierType','BusinessRelationship','TaxOrganizationType'];
const payload=draft.payload;
const keys=payload && typeof payload==='object' && !Array.isArray(payload) ? Object.keys(payload) : [];
if (draft.classificationsVerified!==true || draft.kind!=='supplier' || !draft.source || ['ACTIVE','INACTIVE'].indexOf(draft.source.Status)<0 || !draft.source.SupplierId || keys.length!==fields.length || keys.some(function(key){return fields.indexOf(key)<0;}) || fields.some(function(key){return typeof payload[key]!=='string' || !payload[key].trim() || payload[key].length>(key==='Supplier'?360:80);}) || draft.duplicateCheckedRevision!==draft.revision) {result.reason='The draft needs a verified source, all approved fields, and a current duplicate-name check before review.';return result;}
if (command.action==='review') {draft.status='reviewed';draft.reviewedRevision=draft.revision;result.payload=JSON.parse(JSON.stringify(payload));result.source=JSON.parse(JSON.stringify(draft.source));result.confirmCommand='Confirm request '+draft.requestId+' revision '+draft.revision;result.reason='Review the proposed supplier. Nothing has been created.';return result;}
if (command.action!=='confirm' || draft.status!=='reviewed' || draft.reviewedRevision!==draft.revision) {result.reason='Review the current revision before confirming it.';return result;}
const frozen={requestId:draft.requestId,revision:draft.revision,kind:'supplier',status:'reserved',sourceSupplierId:draft.source.SupplierId,payload:JSON.parse(JSON.stringify(payload))};
state.attempts.push(frozen);draft.status='reserved';result.operation='create_supplier';result.attempt=JSON.parse(JSON.stringify(frozen));result.reason='Request reserved; persist this state before dispatch.';
return result;
